'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'¥'+(Number(n||0)/100).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
const lines=v=>String(v||'').split('\n').map(x=>x.trim()).filter(Boolean);
const roles={owner:'机构负责人',admin:'管理员',teacher:'讲师',operator:'运营',learner:'普通成员'};
const states={draft:'草稿',submitted:'待审核',published:'已发布',pending:'待跟进',following:'跟进中',quoted:'已报价',confirmed:'已确认',closed:'已关闭',sent:'待客户确认',accepted:'客户已确认',superseded:'已被替代'};
const cats={F:'通用基础',T:'工具入门',P:'案例实战',B:'商业交付'};
const S={user:null,memberships:[],orgs:[],org:'',trainingThemes:[],trainingTheme:'aigc-video',courses:[],cart:[],category:'',theme:'',search:'',plan:{},savedId:null,revision:0,preview:null,edit:null,agent:null};
const planDefaults=()=>({title:'',audience:'社会学员',notes:'',introduction:'',promotion:'',subtitle:'',objectives:[],highlights:[],days:2,daily_minutes:360,people:20,batches:1,budget_fen:null,equivalent:false,expected_versions:{}});
S.plan=planDefaults();
const role=()=>S.memberships.find(x=>x.id===S.org)?.role;
const admin=()=>['owner','admin'].includes(role());
const manager=()=>['owner','admin','teacher','operator'].includes(role());
const staff=()=>['owner','admin','operator'].includes(role());
const action=(label,a,id='',cls='')=>`<button type="button" class="btn ${cls}" data-action="${a}" data-id="${esc(id)}">${esc(label)}</button>`;
const link=(label,hash,cls='')=>`<a class="btn ${cls}" href="#${hash}">${esc(label)}</a>`;
const field=(label,name,value='',type='text',extra='')=>`<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const area=(label,name,value='',extra='')=>`<label class="full">${esc(label)}<textarea name="${name}" ${extra}>${esc(value)}</textarea></label>`;
const select=(label,name,options,value,extra='')=>`<label>${esc(label)}<select name="${name}" ${extra}>${options.map(o=>{let [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`}).join('')}</select></label>`;
const list=v=>`<ul>${(v||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;
const notice=v=>v?.length?`<div class="notice">${list(v)}</div>`:'';
const head=(title,sub='',buttons='')=>`<div class="pagehead"><div><div class="eyebrow">COURSE STUDIO / ${esc(S.orgs.find(x=>x.id===S.org)?.name||'')}</div><h1>${esc(title)}</h1><p class="muted">${esc(sub)}</p></div><div class="actions noprint">${buttons}</div></div>`;
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(S.toastTimer);S.toastTimer=setTimeout(()=>$('#toast').style.display='none',5000)}
function modal(title,body){delete $('#dialog').dataset.studioJob;$('#dialog').classList.remove('course-dialog');$('#dialog-content').innerHTML=`<div class="dialoghead"><h2 id="dialog-title">${esc(title)}</h2>${action('关闭','close','','small')}</div>${body}<div id="dialog-error" class="error" role="alert"></div>`;if(!$('#dialog').open)$('#dialog').showModal()}
function error(e){const text=e.message||String(e);if($('#dialog').open && $('#dialog-error'))$('#dialog-error').textContent=text;toast(text)}
async function api(path,method='GET',body){const headers={'X-Requested-With':'course-platform'};if(S.user)headers['X-CSRF-Token']=S.user.csrf;if(body&&!(body instanceof FormData))headers['Content-Type']='application/json';const r=await fetch('/api'+path,{method,headers,credentials:'same-origin',body:body instanceof FormData?body:body?JSON.stringify(body):undefined});let d=await r.json();if(!r.ok){const m=Array.isArray(d.detail)?d.detail.map(x=>`${x.loc?.slice(1).join('.')}：${x.msg}`).join('\n'):d.detail;throw new Error(m||'请求失败')}return d}
function download(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function requireLogin(){if(S.user)return true;auth('login');return false}
async function refreshIdentity(){const x=await api('/auth/me');S.user=x.user;S.memberships=x.memberships;nav()}
function nav(){
 $('#org-context-label').textContent=S.user?'当前机构':'课程提供机构';
 const r=role(),page=location.hash.slice(1).split('?')[0]||'catalog',mobile=matchMedia('(max-width:850px)').matches;
 $('#userbar').innerHTML=S.user?`<details class="account-menu"><summary aria-label="账户菜单"><span class="account-avatar">${esc(S.user.name.slice(0,1))}</span><span class="account-name">${esc(S.user.name)}</span><span class="chevron" aria-hidden="true"></span></summary><div class="account-dropdown"><p>${esc(roles[r]||'普通用户')}</p><a href="#my-organizations">我的机构</a><a href="#settings">账号与设置</a>${action('退出','logout','','small')}</div></details>`:action('登录 / 注册','login','','small');
 const groups=[{title:'课程中心',keys:['catalog','paths'],items:[['catalog','课程目录'],['paths','学习路径']]},{title:'培训方案',keys:['plan','agent','saved','creative','inquiries',...(!staff()?['inquiry']:[])],items:[['plan',`课程组合 (${S.cart.length})`],['agent','智能组课'],...(S.user?[['saved','已存方案'],['creative','宣传素材'],['inquiries','我的询价']]:[])]},...(manager()?[{title:'机构管理',keys:['workspace','modules','edit','members','departments','audit','work-inquiries',...(staff()?['inquiry']:[])],items:[['workspace','工作概览'],['modules','课程管理'],...(staff()?[['work-inquiries','客户询价']]:[]),...(admin()?[['members','机构成员'],['departments','组织架构'],['audit','操作记录']]:[])]}]:[]),...(S.user?.platform_admin?[{title:'平台管理',keys:['platform-orgs','platform-users'],items:[['platform-orgs','机构管理'],['platform-users','用户管理']]}]:[])];
 $('#navigation').innerHTML=groups.map((g,i)=>`<details class="nav-group ${g.keys.includes(page)?'current-group':''}" ${g.keys.includes(page)&&!mobile?'open':''}><summary><span class="nav-index">0${i+1}</span>${g.title}<span class="chevron" aria-hidden="true"></span></summary><div class="nav-submenu">${g.items.map(([k,v])=>`<a href="#${k}" ${page===k?'aria-current="page"':''} class="${page===k?'active':''}">${esc(v)}</a>`).join('')}</div></details>`).join('');
}
function remember(){localStorage.setItem('course-studio-cart-'+S.org,JSON.stringify(S.cart));nav()}
async function loadOrg(id){S.org=id;S.courses=await api('/catalog?org='+encodeURIComponent(id));try{S.cart=JSON.parse(localStorage.getItem('course-studio-cart-'+id)||'[]').filter(x=>S.courses.some(c=>c.id===x))}catch{S.cart=[]}S.plan=planDefaults();S.savedId=null;S.preview=null;S.agent=null;nav()}
async function init(){const themeResponse=await fetch('/static/training-themes.json');if(!themeResponse.ok)throw Error('培训主题读取失败');S.trainingThemes=(await themeResponse.json()).filter(t=>t.status==='active');$('#training-theme-select').innerHTML=S.trainingThemes.map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('');$('#training-theme-select').value=S.trainingTheme;const config=await api('/assets/config');S.uploadLimit=config.max_upload_mb;await refreshIdentity();S.orgs=await api('/orgs');$('#org-select').innerHTML=S.orgs.map(o=>`<option value="${esc(o.id)}">${esc(o.name)}</option>`).join('');if(S.orgs.length){const own=S.memberships.find(m=>S.orgs.some(o=>o.id===m.id));await loadOrg(own?.id||S.orgs[0].id);$('#org-select').value=S.org;}await route();const token=new URLSearchParams(location.search).get('invite');if(token)modal('加入机构',`<p>请先使用被邀请的邮箱登录或注册，再接受邀请。链接有效期为 7 天。</p><div class="actions">${action('登录 / 注册','login')}${action('接受邀请','accept-invite',token,'primary')}</div>`)}
function auth(mode){modal(mode==='register'?'创建账号':'欢迎回来',`<form id="auth-form" data-mode="${mode}" class="form-grid">${mode==='register'?field('姓名','name','','text','required maxlength="80"'):''}${field('邮箱','email','','email','required autocomplete="username"')}${field('密码（至少10位）','password','','password','required minlength="10" maxlength="128" autocomplete="'+(mode==='register'?'new-password':'current-password')+'"')}<div class="full actions"><button class="btn primary" type="submit">${mode==='register'?'注册':'登录'}</button>${action(mode==='register'?'已有账号，去登录':'注册普通账号',mode==='register'?'login':'register')}</div><p class="hint full">注册后即可保存方案、组课和询价。通过邀请或管理员分配加入机构。</p></form>`)}
function catalog(){const cs=S.courses.filter(c=>(!S.category||c.category===S.category)&&(!S.theme||(c.title+c.intro+c.track).includes(S.theme))&&(!S.search||(c.title+c.code+c.intro+c.tools).toLowerCase().includes(S.search.toLowerCase())));$('#content').innerHTML=`<section class="hero catalog-hero"><div class="hero-copy"><div class="eyebrow"><span></span> AI视频创作 · 专业实训课程</div><h1>AI视频创作<br><em>从工具应用到专业交付</em></h1><p>面向院校教学、企业培训与个人进修，系统学习创意策划、视频制作与项目交付。根据学习目标与培训周期，定制适合您的课程方案。</p><div class="actions hero-actions">${action('浏览课程目录','browse-courses','','hero-primary')}${link('定制培训方案','agent','hero-secondary')}</div><div class="hero-topics">广告与品牌内容<span> / </span>口播与教学视频<span> / </span>短剧与转绘制作</div></div><div class="hero-metrics"><div><strong>${S.courses.length}<small>门</small></strong><span>模块化课程</span></div><div><strong>${S.courses.reduce((n,c)=>n+c.minutes,0)/60}<small>小时</small></strong><span>系统课程内容</span></div><div><strong>1–7<small>天</small></strong><span>灵活安排培训周期</span></div></div></section><div class="catalog-layout"><section class="catalog-main" id="course-list"><div class="categories">${Object.entries(cats).map(([k,v])=>`<button class="category type-${k}" data-action="category" data-id="${k}" aria-pressed="${S.category===k}"><b>${k}</b>${v}<small>${S.courses.filter(c=>c.category===k).length} 门模块</small></button>`).join('')}</div><div class="filters"><input id="course-search" aria-label="搜索课程" placeholder="搜索课程名称、技能或工具" value="${esc(S.search)}"><select id="category-filter" aria-label="课程类别"><option value="">全部类别</option>${Object.entries(cats).map(([k,v])=>`<option value="${k}" ${S.category===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="tags">${[['','全部方向'],['转绘','转绘特色'],['短剧','短剧制作'],['口播','广告口播'],['广告','品牌广告'],['教学','教学微课']].map(([k,v])=>`<button class="chip" data-action="theme" data-id="${k}" aria-pressed="${S.theme===k}">${v}</button>`).join('')}</div><p class="hint">找到 ${cs.length} 门课程 · 点击课程详情查看完整课纲与成果标准</p><div class="course-grid">${cs.map(c=>`<article class="course type-${c.category} ${S.cart.includes(c.id)?'selected':''}"><div class="course-meta"><span class="badge type-${c.category}">${c.code} · ${cats[c.category]}</span><span>${c.minutes/60}小时 · ${esc(c.level)}</span></div><h3>${esc(c.title)}</h3><p class="muted">${esc(c.intro)}</p><div class="outcome"><b>课程成果</b><br>${esc(c.output)}</div><div class="course-bottom"><span class="price">${money(c.price_fen)} <small>/ 班次参考</small></span>${action(S.cart.includes(c.id)?'已选 · 移除':'+ 加入组合','cart',c.id,S.cart.includes(c.id)?'small':'small primary')}</div><button class="textbtn" data-action="detail" data-id="${c.id}">查看完整课程 →</button></article>`).join('')||'<div class="empty">没有匹配课程，试试其他关键词。</div>'}</div></section>${cartHTML()}</div>`}
function cartHTML(){const cs=S.cart.map(id=>S.courses.find(c=>c.id===id)).filter(Boolean);return `<aside class="panel cart"><div class="eyebrow">培训方案</div><h2>课程组合 <span class="muted">${cs.length}</span></h2><p class="hint">按授课顺序排列，可补齐前置模块。</p>${cs.map((c,i)=>`<div class="cartitem"><b>${c.code}</b> ${esc(c.title)}<div class="actions"><span class="hint">${c.minutes/60}h · ${money(c.price_fen)}</span><span>${action('↑','up',c.id,'small')}${action('↓','down',c.id,'small')}${action('×','cart',c.id,'small')}</span></div></div>`).join('')||'<p class="muted">请选择课程加入组合。</p>'}<div class="cart-total"><div>共 ${cs.reduce((n,c)=>n+c.minutes,0)/60} 小时</div><span class="price">${money(cs.reduce((n,c)=>n+c.price_fen,0))}</span><p class="hint">每班次模块参考小计。0 元模块不代表整个培训项目免费。</p></div>${link('生成课程方案','plan','primary block')}${action('补齐前置并排序','prereqs','','block')}${action('清空组合','clear-cart','','block small')}</aside>`}
function courseDoc(c){return `<div class="module-doc"><span class="badge type-${c.category}">${esc(c.code||cats[c.category])} · ${c.minutes} 分钟 · 版本 ${c.version||1}</span><h3>${esc(c.title)}</h3><p>${esc(c.description)}</p><h4>适合对象</h4><p>${esc(c.audience)}</p><h4>学习目标</h4>${list(c.objectives)}<h4>完整课纲</h4>${c.syllabus.map(u=>`<div class="lesson-step"><b>${esc(u.name)} · ${u.minutes} 分钟</b>${list(u.points)}<p class="hint">教学活动：${esc(u.activity)}</p></div>`).join('')}<h4>实操与成果</h4><p>${esc(c.exercise)}</p><p><b>交付成果：</b>${esc(c.output)}</p><h4>评价标准</h4>${list(c.criteria)}<h4>课前准备</h4>${list(c.materials)}<p><b>课后任务：</b>${esc(c.homework)}</p><p><b>工具：</b>${esc(c.tools)}<br><b>实施说明：</b>${esc(c.note||'结合学员基础调整演示与练习比例。')}</p>${c.method_cards?.length?`<h4>镜头方法卡</h4>${c.method_cards.map(m=>`<details><summary>${esc(m.title||m.name||m.stage||'方法卡')}</summary><pre class="codebox">${esc(JSON.stringify(m,null,2))}</pre></details>`).join('')}`:''}${c.shot_template?`<h4>镜头施工单</h4><p>${esc(c.shot_template)}</p>`:''}<p><b>模块参考价：</b>${money(c.price_fen)} / 班次 · 建议每班 ${c.class_size} 人<br>${esc(c.price_scope)}</p></div>`}
function planPayload(){return {org_id:S.org,ids:S.cart,...S.plan,revision:S.revision}}
function readPlan(form){const d=Object.fromEntries(new FormData(form));S.plan={...S.plan,title:d.title,audience:d.audience,notes:d.notes,introduction:d.introduction,promotion:d.promotion,subtitle:d.subtitle,objectives:lines(d.objectives),highlights:lines(d.highlights),days:+d.days,daily_minutes:+d.daily_minutes,people:+d.people,batches:+d.batches,budget_fen:d.budget===''?null:Math.round(+d.budget*100),equivalent:d.equivalent==='on'};S.preview=null}
function planForm(){const p=S.plan;return `<form id="plan-form" class="panel noprint"><div class="form-grid cols3">${field('方案名称（留空自动命名）','title',p.title,'text','maxlength="150"')}${field('培训对象','audience',p.audience,'text','required maxlength="200"')}${field('目标天数（0表示不限）','days',p.days,'number','min="0" max="30" required')}${field('每日净教学分钟','daily_minutes',p.daily_minutes,'number','min="60" max="480" required')}${field('每班人数','people',p.people,'number','min="1" max="10000" required')}${field('培训班次','batches',p.batches,'number','min="1" max="100" required')}${field('模块预算（元，留空不限）','budget',p.budget_fen===null?'':p.budget_fen/100,'number','min="0" step="0.01"')}${area('培训重点与备注','notes',p.notes,'maxlength="3000"')}${field('课程副标题','subtitle',p.subtitle||'','text','maxlength="100"')}${area('培训目标（每行一条，最多8条）','objectives',(p.objectives||[]).join('\n'),'maxlength="1600"')}${area('课程亮点（每行一条，最多6条）','highlights',(p.highlights||[]).join('\n'),'maxlength="1200"')}${area('课程简介草稿（留空自动生成）','introduction',p.introduction,'maxlength="4000"')}${area('宣传摘要草稿（留空自动生成）','promotion',p.promotion,'maxlength="4000"')}<label class="check full"><input name="equivalent" type="checkbox" ${p.equivalent?'checked':''}>学员已具备同等前置能力，可省略基础模块</label></div><div class="actions form-actions"><button class="btn primary" type="submit">生成 / 更新教案</button>${action('AI生成课程信息','studio-copy')}${action('制作宣传海报','studio-poster')}${action('保存方案','save-plan')}${action('提交询价','inquire')}${action('补齐前置并排序','prereqs')}${action('确认使用课程当前版本','current-versions')}</div><p class="hint">全天课程建议 360 分钟净教学；课间、午休和环境安装另计。调整顺序请返回课程菜单。</p></form>`}
function planDoc(p){const cs=Object.fromEntries(p.courses.map(c=>[c.id,c]));return `<article class="doc"><div class="eyebrow">培训方案 · 教案草稿</div><h1>${esc(p.title)}</h1>${p.subtitle?`<p class="muted">${esc(p.subtitle)}</p>`:''}<div class="summary"><span>${esc(p.audience)}</span><span>${p.total_minutes/60} 小时</span><span>${p.courses.length} 个模块</span><span>${p.batches} 班次 / ${p.people} 人每班</span><span>${money(p.subtotal_fen)} 参考小计</span></div><p>${esc(p.introduction||`通过 ${p.courses.length} 个原子模块，将视频创作方法、工具操作与案例练习组合成连续的学习路径。每个模块包含明确成果与评价标准。`)}</p>${p.objectives?.length?'<h2>培训目标</h2>'+list(p.objectives):''}${p.highlights?.length?'<h2>课程亮点</h2>'+list(p.highlights):''}${notice(p.warnings)}<p class="hint">${esc(p.price_note)}</p>${p.notes?`<p>需求重点：${esc(p.notes)}</p>`:''}${p.schedule.map((d,i)=>`<h2>第 ${i+1} 天 · ${d.minutes} 分钟</h2>${d.courses.map(id=>courseDoc(cs[id])).join('')}`).join('')}<h2>宣传摘要</h2><p>${esc(p.promotion||`面向${p.audience}，以实际作品为线索开展 ${p.total_minutes/60} 小时训练。覆盖${p.courses.slice(0,5).map(c=>c.title.split('：')[0]).join('、')}。课程成果以教学练习和方案约定为准。`)}</p><p class="hint">宣传草稿供机构复核；不承诺接单数量、收益或作品传播效果。</p></article>`}
async function planView(){if(!S.cart.length){$('#content').innerHTML=head('我的课程组合','选择课程模块，或根据培训需求生成课程建议。',action('导入组合','import'))+`<div class="empty"><p>组合中还没有课程</p>${link('挑选课程','catalog','primary')} ${link('智能组课','agent')}</div>`;return}$('#content').innerHTML=head('培训方案设计','按培训对象、教学周期与预算组合课程，生成课程安排及教学方案。',action('导出 JSON','export-json')+action('导入方案','import')+action('导出教案','export-md')+action('打印 / PDF','print'))+planForm()+`<div id="plan-output"></div>`;if(S.preview)$('#plan-output').innerHTML=planDoc(S.preview);else await previewPlan()}
async function previewPlan(){S.preview=await api('/plans/validate','POST',planPayload());if($('#plan-output'))$('#plan-output').innerHTML=planDoc(S.preview);return S.preview}
function exportMd(p){let s=`# ${p.title}\n\n对象：${p.audience}\n净教学：${p.total_minutes} 分钟\n模块参考小计：${money(p.subtotal_fen)}\n${p.price_note}\n\n`;s+='## 课程简介\n'+(p.introduction||`通过${p.courses.length}个模块，完成方法学习、案例练习和成果检查。`)+'\n';if(p.subtitle)s+='\n'+p.subtitle+'\n';if(p.objectives?.length)s+='\n## 培训目标\n'+p.objectives.map(x=>'- '+x).join('\n')+'\n';if(p.highlights?.length)s+='\n## 课程亮点\n'+p.highlights.map(x=>'- '+x).join('\n')+'\n';s+=p.warnings.map(x=>'- '+x).join('\n')+'\n';for(const [i,d]of p.schedule.entries()){s+=`\n## 第 ${i+1} 天 · ${d.minutes} 分钟\n`;for(const id of d.courses){const c=p.courses.find(x=>x.id===id);s+=`\n### ${c.code} ${c.title} · v${c.version}\n${c.description}\n目标：${c.objectives.join('；')}\n`;for(const u of c.syllabus)s+=`- ${u.name}（${u.minutes}分钟）：${u.points.join('；')}。教学活动：${u.activity}\n`;s+=`练习：${c.exercise}\n成果：${c.output}\n评价：${c.criteria.join('；')}\n准备：${c.materials.join('；')}\n课后：${c.homework}\n费用范围：${c.price_scope}\n`}}s+='\n## 宣传摘要\n'+(p.promotion||`面向${p.audience}的${p.total_minutes/60}小时视频创作课程，以实际作品为线索学习${p.courses.slice(0,5).map(c=>c.title).join('、')}。具体授课范围以方案为准。`);return s}
function prerequisites(){const map=Object.fromEntries(S.courses.map(c=>[c.id,c]));const result=[],visiting=new Set();function visit(id){if(result.includes(id))return;if(visiting.has(id)||!map[id])throw new Error('前置课程不可用，请联系机构');visiting.add(id);const c=map[id];let ds=c.prereq_ids||[];if(c.prereq_mode==='any'&&ds.length)ds=[ds.find(x=>S.cart.includes(x))||ds.find(x=>map[x])];if(!S.plan.equivalent)ds.forEach(visit);visiting.delete(id);result.push(id)}S.cart.forEach(visit);S.cart=result;S.preview=null;remember()}
async function savedView(){if(!requireLogin())return;const ps=await api('/plans');S.saved=ps;$('#content').innerHTML=head('已存方案','账号下的方案持久保存在本机数据库中。',action('导入旧版组合','import'))+`<div class="panel table-wrap"><table><thead><tr><th>方案名称</th><th>模块 / 课时</th><th>参考小计</th><th>操作</th></tr></thead><tbody>${ps.map(p=>`<tr><td>${esc(p.title)}<small> · 修订 ${p.revision}</small></td><td>${p.data.ids.length} / ${p.data.total_minutes/60}h</td><td>${money(p.data.subtotal_fen)}</td><td>${action('载入','load-plan',p.id,'small')}</td></tr>`).join('')}</tbody></table>${!ps.length?'<p class="muted">还没有保存的方案。</p>':''}</div>`}
async function agentView(){const cfg=await api('/agent/config');$('#content').innerHTML=head('智能组课','根据培训目标、学员基础、教学周期与预算，推荐课程组合及教学安排。')+`<form id="agent-form" class="panel"><div class="form-grid cols3">${select('课程主题','theme',['转绘','短剧','口播','广告','教学','综合'],'转绘')}${field('培训对象','audience','社会学员','text','required maxlength="200"')}${select('学习起点','level',['入门','进阶'],'入门')}${field('天数','days',2,'number','min="1" max="14" required')}${field('每日净教学分钟','daily_minutes',360,'number','min="60" max="480" required')}${field('每班人数','people',20,'number','min="1" max="1000" required')}${field('模块预算（元，留空不限）','budget','','number','min="0" step="0.01"')}${select('生成方式','mode',cfg.ai_available?[['rules','规则组课'],['ai','规则选课 + AI文案']]:[['rules','规则组课']],'rules')}${area('教学重点（AI模式下会提交给所配服务）','notes','','maxlength="1500"')}<label class="check full"><input name="required" type="checkbox">优先保留当前组合的 ${S.cart.length} 个模块（最多20个）</label><label class="check full"><input name="equivalent" type="checkbox">学员已有同等前置能力</label></div><div class="form-actions"><button class="btn primary" type="submit">生成组课建议</button><p class="hint">按课程主题、先修要求、学时与预算匹配课程。${cfg.ai_available?'AI模式仅润色已验证方案的简介和宣传草稿。':'当前提供规则组课，AI文案服务暂未启用。'} 预算只约束模块参考价。</p></div></form><div id="agent-result">${S.agent?agentResult(S.agent):''}</div>`}
function agentResult(a){return `<section class="panel"><span class="badge type-P">${a.plan.mode==='ai-assisted'?'AI文案 + 规则选课':a.plan.mode==='rules-fallback'?'规则方案 · AI调用未成功':'规则组课结果'}</span><h2>${esc(a.plan.title)}</h2>${notice(a.plan.limitations)}<div class="table-wrap"><table><thead><tr><th>推荐课程</th><th>选择原因</th><th>时长</th></tr></thead><tbody>${a.plan.courses.map(c=>`<tr><td>${esc(c.code+' '+c.title)}</td><td>${esc(a.plan.reasons[c.id])}</td><td>${c.minutes}分钟</td></tr>`).join('')}</tbody></table></div><div class="actions form-actions">${action('采用方案并编辑','apply-agent','','primary')}${action('导出教案','agent-export')}</div></section>${planDoc(a.plan)}`}
async function workspace(){const d=await api('/orgs/'+S.org+'/overview');$('#content').innerHTML=head('机构工作台',d.org.name+' · '+roles[d.role])+`<div class="stats">${[['课程模块',d.modules],['等待审核',d.pending],['待跟进询价',d.inquiries??'—']].map(([t,n])=>`<div class="stat"><small>${t}</small><b>${n}</b></div>`).join('')}</div><div class="grid2"><section class="panel"><h2>课程生产</h2><p class="muted">集中管理课程内容、参考定价、教学资源与发布审核。</p><div class="actions">${link('管理课程','modules','primary')}${link('创建模块','edit')}</div></section><section class="panel"><h2>培训交付</h2><p class="muted">管理培训需求、课程方案及项目报价，统一授权教学资源。</p><div class="actions">${link('智能组课','agent','primary')}${staff()?link('处理询价','work-inquiries'):link('课程菜单','catalog')}</div></section></div><div class="panel"><h3>机构介绍</h3><p>${esc(d.org.description)}</p><p class="hint">当前账号在本机构的权限：${roles[d.role]}。资源、成员和业务数据按机构隔离。</p></div>`}
async function modulesView(){const ms=await api('/orgs/'+S.org+'/modules');$('#content').innerHTML=head('课程管理','课程修改先保存为草稿，审核通过后更新对外菜单。',link('创建课程模块','edit','primary'))+`<div class="panel table-wrap"><table><thead><tr><th>课程</th><th>当前版本</th><th>状态</th><th>操作</th></tr></thead><tbody>${ms.map(m=>`<tr><td class="row-title">${esc(m.code+' '+m.title)}<small>${esc(m.reason)}</small></td><td>v${m.number}</td><td><span class="badge type-${m.code[0]}">${states[m.state]}</span> ${!m.active?'已下架':''}${m.draft_id&&m.published_id?' · 线上旧版仍可选':''}</td><td>${m.editable?link('管理 / 审核','edit?id='+m.id,'small'):'他人课程'}</td></tr>`).join('')}</tbody></table></div>`}
function unitRow(u={name:'',minutes:15,points:[],activity:''}){return `<div class="unit-row"><label>分钟<input name="unit_minutes" type="number" min="1" max="480" value="${u.minutes}" required></label><label>环节名称<input name="unit_name" value="${esc(u.name)}" maxlength="100" required></label><button type="button" class="textbtn" data-action="remove-unit" aria-label="移除课纲环节">×</button><label class="full">知识点（每行一个）<textarea name="unit_points">${esc(u.points.join('\n'))}</textarea></label><label class="activity">教学活动<textarea name="unit_activity" maxlength="1500">${esc(u.activity)}</textarea></label></div>`}
async function editView(id){let m=null,c={title:'',category:'P',minutes:60,price_fen:0,class_size:30,delivery:'线上或线下',visibility:'public',track:'通用',tools:'',level:'入门',audience:'社会学员',objectives:[],syllabus:[{name:'方法讲解',minutes:15,points:[],activity:''},{name:'案例实操',minutes:35,points:[],activity:''},{name:'成果点评',minutes:10,points:[],activity:''}],criteria:[],materials:[],prereq_ids:[],prereq_mode:'all',price_scope:'模块内容参考价；师资实施、差旅、场地与AI工具用量以项目报价为准。'};if(id){m=await api('/manage/modules/'+id);c=m.versions[0].data}S.edit={m,c,revision:m?.versions[0].revision||0};const state=m?.versions[0].state,locked=state==='submitted';$('#content').innerHTML=head(id?'课程编辑与审核':'创建课程模块','课程简介、教案、资源与报价信息在同一处维护。',link('返回课程列表','modules'))+(m?`<div class="panel"><div class="actions"><span class="badge type-${c.category}">${m.code} · v${m.versions[0].number} · ${states[state]}${!m.active?' · 已下架':''}</span>${state==='draft'?action('提交审核','review-submit',id,'primary'):''}${locked?action('撤回修改','review-withdraw',id):''}${locked&&admin()?action('审核通过并发布','review-approve',id,'primary')+action('退回修改','review-reject',id,'danger'):''}${m.published_id&&admin()?action(m.active?'下架课程':'重新上架',m.active?'review-unpublish':'review-republish',id):''}</div>${m.versions[0].reason?notice([m.versions[0].reason]):''}</div>`:'')+`<form id="module-form"><fieldset ${locked?'disabled':''}><legend>基本信息</legend><div class="form-grid">${field('课程名称','title',c.title,'text','required minlength="2" maxlength="150"')}${select('课程类别','category',Object.entries(cats),c.category,id?'disabled':'')}${field('总时长（分钟）','minutes',c.minutes,'number','min="15" max="480" required')}${field('主题方向','track',c.track)}${field('适合对象','audience',c.audience,'text','required maxlength="500"')}${select('学习起点','level',['入门','进阶','综合'],c.level)}${field('使用工具','tools',c.tools,'text','maxlength="500"')}${field('授课形式','delivery',c.delivery)}${select('可见范围','visibility',[['public','公开可选'],['organization','仅机构成员']],c.visibility)}${field('建议每班人数','class_size',c.class_size,'number','min="1" max="1000" required')}${area('课程简介','intro',c.intro,'required maxlength="1500"')}${area('详细介绍','description',c.description,'required maxlength="6000"')}${area('学习目标（每行一条，最多12条）','objectives',c.objectives.join('\n'),'required')}</div></fieldset><fieldset ${locked?'disabled':''}><legend>完整课纲</legend><p class="hint">各环节分钟数之和必须等于总时长。课纲包含知识点、演示与实操活动。</p><div id="unit-list">${c.syllabus.map(unitRow).join('')}</div>${action('+ 添加教学环节','add-unit')}<div class="form-grid">${area('课堂练习','exercise',c.exercise,'required maxlength="3000"')}${area('交付成果','output',c.output,'required maxlength="1500"')}${area('评价标准（每行一条）','criteria',c.criteria.join('\n'),'required')}${area('课前资料 / 准备（每行一条）','materials',c.materials.join('\n'))}${area('课后任务','homework',c.homework,'maxlength="3000"')}${area('实施备注','note',c.note,'maxlength="3000"')}${field('前置课程编号（逗号分隔，如 F01,T01）','prereq_codes',c.prereq_ids.map(x=>S.courses.find(y=>y.id===x)?.code||x).join(','))}${select('前置关系','prereq_mode',[['all','全部满足'],['any','任一满足']],c.prereq_mode)}</div></fieldset><fieldset ${locked?'disabled':''}><legend>定价与组课提示</legend><div class="form-grid">${field('模块参考价（元 / 班次）','price',c.price_fen/100,'number','min="0" max="1000000" step="0.01" required')}${area('费用范围与计价说明','price_scope',c.price_scope,'required maxlength="1500"')}${area('内部组课 / 宣传提示词','marketing_prompt',c.marketing_prompt,'maxlength="12000"')}<p class="hint full">默认 0 元。提示词保存在后台，不发送给访客；只作为机构内部编辑资料，不能覆盖价格、课时或权限规则。</p></div></fieldset><div class="actions form-actions noprint"><button class="btn primary" type="submit" ${locked?'disabled':''}>${state==='published'?'保存为新版本草稿':'保存草稿'}</button>${link('返回列表','modules')}</div></form>${m?`<section class="panel"><h2>教学资源</h2><p class="hint">公开资源随对应课程版本发布；机构资源仅成员可下载；项目资源需单独授权给询价客户。支持PPT、PDF及录播视频，单个文件最大${S.uploadLimit||512}MB。</p>${m.draft_id&&!locked?`<form id="upload-form" class="form-grid">${field('选择文件','file','','file','required')}${select('资源范围','visibility',[['organization','机构内部'],['public','公开课程资料'],['project','按项目授权']],'organization')}<div class="full"><button class="btn" type="submit">上传到当前草稿</button></div></form>`:'<p class="hint">需要添加资源时，先保存修订草稿。</p>'}<div class="table-wrap"><table><tbody>${m.assets.map(a=>`<tr><td><a href="/api/assets/${a.id}" target="_blank" rel="noopener">${esc(a.name)}</a><small> · ${(a.size/1024).toFixed(1)} KB</small></td><td>${{public:'公开',organization:'机构',project:'项目'}[a.visibility]} · v${m.versions.find(v=>v.id===a.version_id)?.number}</td><td>${a.visibility==='project'&&staff()?action('授权给项目','grant',a.id,'small'):''}${a.version_id===m.draft_id&&!locked?action('移除','delete-asset',a.id,'small danger'):''}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><h3>版本记录</h3>${m.versions.map(v=>`<details class="history-item"><summary>v${v.number} · ${states[v.state]} · ${new Date(v.created*1000).toLocaleString()}</summary><div class="doc">${courseDoc({...v.data,code:m.code,version:v.number})}</div></details>`).join('')}</section>`:''}`}
function readModule(form){const d=Object.fromEntries(new FormData(form)),old=S.edit.c;const prereqs=String(d.prereq_codes||'').split(/[,，\s]+/).filter(Boolean).map(code=>{const c=S.courses.find(c=>c.code===code||c.id===code);if(!c)throw new Error('找不到前置课程 '+code);return c.id});return {...old,...Object.fromEntries(['title','intro','description','track','audience','level','tools','delivery','visibility','exercise','output','homework','note','price_scope','marketing_prompt','prereq_mode'].map(k=>[k,d[k]])),category:d.category||old.category,minutes:+d.minutes,class_size:+d.class_size,price_fen:Math.round(+d.price*100),objectives:lines(d.objectives),criteria:lines(d.criteria),materials:lines(d.materials),prereq_ids:prereqs,syllabus:$$('.unit-row',form).map(row=>({name:$('[name=unit_name]',row).value,minutes:+$('[name=unit_minutes]',row).value,points:lines($('[name=unit_points]',row).value),activity:$('[name=unit_activity]',row).value}))}}
async function inquiryView(work=false){if(!requireLogin())return;const rows=await api('/inquiries'+(work?'?org='+S.org:''));$('#content').innerHTML=head(work?'客户询价':'我的询价','选课快照、联系信息与每轮报价均可追溯。')+`<div class="panel table-wrap"><table><thead><tr><th>需求</th><th>联系人</th><th>参考小计</th><th>状态</th><th>操作</th></tr></thead><tbody>${rows.map(i=>`<tr><td class="row-title">${esc(i.snapshot.title)}<small>${i.id.slice(0,8)} · ${new Date(i.created*1000).toLocaleDateString()}</small></td><td>${esc(i.user_data.contact)}<br><span class="hint">${esc(i.user_data.company)}</span></td><td>${money(i.snapshot.subtotal_fen)}</td><td>${states[i.state]}</td><td>${link('查看','inquiry?id='+i.id,'small')}</td></tr>`).join('')}</tbody></table>${!rows.length?'<p class="muted">暂无询价。</p>':''}</div>`}
function inquiryModal(){modal('提交培训询价',`<p class="hint">课程参考价与当前版本将保存为需求快照。机构在后台查看并报价；本系统不会自动发送邮件。</p><form id="inquiry-form" class="form-grid" data-key="${crypto.randomUUID()}">${field('联系人','contact',S.user?.name||'','text','required maxlength="100"')}${field('电话 / 联系方式','phone','','text','required minlength="3" maxlength="100"')}${field('单位名称','company','','text','maxlength="200"')}${field('培训地点','location','线上','text','maxlength="300"')}${field('期望日期','preferred_date','待定','text','maxlength="100"')}<div class="full"><button class="btn primary" type="submit">确认提交询价</button></div></form>`)}
async function inquiryDetail(id){const i=await api('/inquiries/'+id);S.inquiry=i;const isStaff=S.memberships.some(m=>m.id===i.org_id&&['owner','admin','operator'].includes(m.role)),isAdmin=S.memberships.some(m=>m.id===i.org_id&&['owner','admin'].includes(m.role));$('#content').innerHTML=head('培训需求 · '+id.slice(0,8),i.snapshot.title,link('返回询价',isStaff?'work-inquiries':'inquiries')+action('打印 / PDF','print'))+`<section class="panel"><h2>${states[i.state]}</h2><div class="summary"><span>${esc(i.user_data.contact)}</span><span>${esc(i.user_data.phone)}</span><span>${esc(i.user_data.company||'个人客户')}</span><span>${esc(i.user_data.location)}</span><span>${esc(i.user_data.preferred_date)}</span></div><p class="hint">需求编号：${i.id}</p>${isStaff?`<div class="actions noprint">${select('跟进状态','inquiry-state',Object.entries(states).filter(([k])=>['pending','following','closed'].includes(k)),'following')}${action('更新跟进','inquiry-state',id)}${action('起草项目报价','quote-new',id,'primary')}</div>`:''}</section><section class="panel"><h2>项目报价</h2>${i.quotes.map(q=>`<article class="module-doc quote-doc"><div class="pagehead"><h3>报价 v${q.number} · ${q.expired?'已过期':states[q.state]}</h3><b class="price">${money(q.data.total_fen)}</b></div><div class="table-wrap"><table><thead><tr><th>项目</th><th>数量</th><th>金额</th></tr></thead><tbody>${q.data.module_lines.map(l=>`<tr><td>${esc(l.label)}</td><td>${l.quantity} 班次</td><td>${money(l.amount_fen)}</td></tr>`).join('')}${q.data.extras.map(l=>`<tr><td>${esc(l.label)}</td><td>1</td><td>${money(l.amount_fen)}</td></tr>`).join('')}<tr><td>优惠</td><td></td><td>−${money(q.data.discount_fen)}</td></tr></tbody></table></div><p><b>包含：</b>${esc(q.data.included)}<br><b>不含：</b>${esc(q.data.excluded||'无额外说明')}<br><b>税费：</b>${esc(q.data.tax_note)}<br><b>有效期：</b>${esc(q.data.valid_until)}<br>${esc(q.data.notes)}</p><div class="actions noprint">${q.state==='draft'&&isAdmin&&!q.expired?action('正式发送给客户','quote-send',q.id,'primary'):''}${q.state==='sent'&&!q.expired&&i.user_id===S.user.id?action('确认接受此报价','quote-accept',q.id,'primary'):''}${action('导出报价','quote-export',q.id)}</div></article>`).join('')||'<p class="muted">机构尚未发送报价。</p>'}</section><section class="panel"><h2>项目教学资源</h2>${i.assets.map(a=>`<p><a href="/api/assets/${a.id}" target="_blank" rel="noopener">${esc(a.name)}</a></p>`).join('')||'<p class="muted">暂无授权资源。</p>'}</section><details class="panel"><summary>查看提交时的课程方案（不可变快照）</summary>${planDoc(i.snapshot)}</details>`}
function quoteModal(id){const dt=new Date(Date.now()+14*864e5).toISOString().slice(0,10);modal('起草项目报价',`<p class="hint">模块部分使用客户提交时的价格快照；实施、差旅等费用按实际情况列明。发送新报价后，上一份未确认报价自动失效。</p><form id="quote-form" data-id="${id}" class="form-grid">${area('额外费用（每行：名称 | 金额元）','extras','授课实施服务 | 0')}${field('优惠金额（元）','discount',0,'number','min="0" step="0.01" required')}${field('报价有效期','valid_until',dt,'date','required')}${area('费用包含','included','所选模块教学内容与约定教学成果。','required maxlength="3000"')}${area('费用不含','excluded','差旅、场地、AI工具调用费用，另行协商。','maxlength="3000"')}${field('税费口径','tax_note','税费口径待双方确认','text','maxlength="500"')}${area('备注','notes','','maxlength="3000"')}<div class="full"><button class="btn primary" type="submit">保存报价草稿</button></div></form>`)}
async function settingsView(){const ov=manager()?await api('/orgs/'+S.org+'/overview'):null;$('#content').innerHTML=head('设置','账号安全、机构信息与运行方式。')+`<section class="panel"><h2>修改密码</h2><form id="password-form" class="form-grid">${field('当前密码','current','','password','required autocomplete="current-password"')}${field('新密码（至少10位）','password','','password','required minlength="10" maxlength="128" autocomplete="new-password"')}<div class="full"><button class="btn" type="submit">更新密码</button></div></form></section>${admin()?`<section class="panel"><h2>机构设置</h2><form id="org-form" class="form-grid">${field('机构名称','name',ov.org.name,'text','required minlength="2" maxlength="100"')}${field('每个账号每日组课次数','agent_daily_limit',ov.org.agent_daily_limit,'number','min="1" max="1000" required')}${area('机构介绍','description',ov.org.description,'maxlength="2000"')}<div class="full"><button class="btn primary" type="submit">保存机构设置</button></div></form></section>`:''}${S.user?.platform_admin?`<section class="panel"><h2>创建机构</h2><form id="create-org-form" class="form-grid">${field('机构名称','name','','text','required minlength="2" maxlength="100"')}${field('负责人的已注册邮箱','owner_email','','email','required')}${area('机构介绍','description','','maxlength="2000"')}<div class="full"><button class="btn" type="submit">创建机构</button></div></form></section>`:''}<section class="panel"><h2>智能组课服务</h2><p>默认使用规则引擎，根据主题、起点、前置课程、完整课时与模块预算选择课程。真实 AI 可通过服务器环境变量配置，用于已验证方案的文案生成。</p><p class="hint">API 密钥只存放于服务器配置，不在浏览器中保存。详见随系统附带的部署说明。</p></section>`}
async function route(){nav();const [page='catalog',query='']=location.hash.slice(1).split('?'),q=new URLSearchParams(query);$('#content').innerHTML='<div class="loading">正在读取课程与方案…</div>';try{if(!S.orgs.length&&!['platform-orgs','platform-users','my-organizations','settings'].includes(page)){$('#content').innerHTML='<div class="empty">请先运行初始化命令创建机构。</div>';return}const routes={catalog,paths:pathsView,plan:planView,saved:savedView,creative:studioHistory,agent:agentView,workspace,modules:modulesView,edit:()=>editView(q.get('id')),members:peopleView,departments:departmentsView,'platform-orgs':platformOrgsView,'platform-users':platformUsersView,'my-organizations':myOrganizationsView,inquiries:()=>inquiryView(), 'work-inquiries':()=>inquiryView(true),inquiry:()=>inquiryDetail(q.get('id')),settings:settingsView,audit:async()=>{const rows=await api('/orgs/'+S.org+'/audit');$('#content').innerHTML=head('操作记录','最近100条机构操作，用于核对发布、人员与项目变更。')+`<div class="panel table-wrap"><table><thead><tr><th>时间</th><th>操作者</th><th>操作</th><th>对象</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${new Date(r.created*1000).toLocaleString()}</td><td>${esc(r.actor||'系统')}</td><td>${esc(r.action)}</td><td>${esc(r.target)}</td></tr>`).join('')}</tbody></table></div>`}};await(routes[page||'catalog']||catalog)()}catch(e){$('#content').innerHTML=head('暂时无法打开此页面',e.message,link('返回课程菜单','catalog'));error(e)}}
async function setFromPlan(p,id=null,revision=0){if(p.org_id&&p.org_id!==S.org){if(!S.orgs.some(o=>o.id===p.org_id))throw new Error('方案所属机构不可用');await loadOrg(p.org_id);$('#org-select').value=S.org}S.cart=[...p.ids];S.plan={...planDefaults(),...Object.fromEntries(Object.keys(planDefaults()).filter(k=>k in p).map(k=>[k,p[k]])),expected_versions:p.versions||p.expected_versions||{}};S.savedId=id;S.revision=revision;S.preview=p.courses?p:null;remember();location.hash='plan';await route()}
async function clickAction(e){const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;try{
if(a==='close'){$('#dialog').close();return}if(a==='login'||a==='register'){auth(a);return}
if(a==='logout'){await api('/auth/logout','POST',{});S.user=null;S.memberships=[];S.plan=planDefaults();S.preview=null;S.agent=null;S.edit=null;S.saved=null;S.inquiry=null;S.detailCourse=null;Studio.job=null;Studio.image=null;Studio.result=null;S.savedId=null;S.courses=await api('/catalog?org='+S.org);S.cart=S.cart.filter(id=>S.courses.some(c=>c.id===id));remember();location.hash='catalog';await route();return}
if(a==='accept-invite'){if(!requireLogin())return;const r=await api('/invites/accept','POST',{token:id});$('#dialog').close();history.replaceState(null,'',location.pathname+'#my-organizations');await refreshIdentity();await loadOrg(r.org_id);$('#org-select').value=r.org_id;await route();toast('已加入机构');return}
if(a==='category'){S.category=S.category===id?'':id;catalog();return}if(a==='theme'){S.theme=id;catalog();return}
if(a==='cart'){S.cart=S.cart.includes(id)?S.cart.filter(x=>x!==id):[...S.cart,id];S.preview=null;remember();catalog();return}
if(a==='up'||a==='down'){const i=S.cart.indexOf(id),j=i+(a==='up'?-1:1);if(j>=0&&j<S.cart.length)[S.cart[i],S.cart[j]]=[S.cart[j],S.cart[i]];S.preview=null;remember();catalog();return}
if(a==='clear-cart'){if(!confirm('清空当前组合？已保存的方案不受影响。'))return;S.cart=[];S.preview=null;S.savedId=null;remember();catalog();return}
if(a==='detail'){const c=await api('/modules/'+id);renderCourseDetail(c);return}
if(a==='detail-tab'){renderCourseDetail(S.detailCourse,id);$('#detail-tab-'+id).focus();return}
if(a==='detail-cart'){S.cart=S.cart.includes(id)?S.cart.filter(x=>x!==id):[...S.cart,id];S.preview=null;remember();catalog();renderCourseDetail(S.detailCourse,S.detailTab);return}
if(a==='preview-resource'){previewResource(id);return}
if(a==='close-preview'){$('#resource-viewer').replaceChildren();return}
if(a==='browse-courses'){$('#course-list').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'start'});$('#course-search').focus({preventScroll:true});return}
if(a==='prereqs'){if($('#plan-form'))readPlan($('#plan-form'));prerequisites();await route();toast('前置课程已补齐并排序');return}
if(a==='print'){window.print();return}if(a==='current-versions'){if($('#plan-form'))readPlan($('#plan-form'));S.courses=await api('/catalog?org='+S.org);S.plan.expected_versions={};await previewPlan();toast('已按当前发布版本更新');return}
if(['save-plan','inquire','export-json','export-md'].includes(a)){if($('#plan-form')){if(!$('#plan-form').reportValidity())return;readPlan($('#plan-form'))}const p=await previewPlan();if(a==='export-json')download('课程组合.json',JSON.stringify({schema:'course-studio/v1',plan:{...planPayload(),expected_versions:p.versions}},null,2),'application/json');if(a==='export-md')download(p.title+'.md',exportMd(p));if(a==='save-plan'&&requireLogin()){const r=await api('/plans'+(S.savedId?'/'+S.savedId:''),S.savedId?'PUT':'POST',planPayload());S.savedId=r.id;S.revision=r.revision;S.preview=r.plan;S.plan.expected_versions=r.plan.versions;toast('方案已保存')}if(a==='inquire'&&requireLogin()){S.plan.expected_versions=p.versions;inquiryModal()}return}
if(a==='import'){modal('导入课程组合',`<p>支持本系统导出的 JSON，以及原课程菜单的 aigc-course-plan/v2 组合文件。导入后请核对课程与价格。</p><form id="import-form">${field('组合 JSON 文件','file','','file','accept=".json" required')}<div class="form-actions"><button class="btn primary" type="submit">读取并载入</button></div></form>`);return}
if(a==='load-plan'){const p=S.saved.find(x=>x.id===id);await setFromPlan(p.data,p.id,p.revision);return}
if(a==='apply-agent'){await setFromPlan(S.agent.plan);toast('已采用建议，可继续调整模块和课时');return}if(a==='agent-export'){download(S.agent.plan.title+'.md',S.agent.markdown);return}
if(a==='add-unit'){$('#unit-list').insertAdjacentHTML('beforeend',unitRow());return}if(a==='remove-unit'){b.closest('.unit-row').remove();return}
if(a.startsWith('review-')){const type=a.slice(7);let reason='';if(type==='reject'){reason=prompt('填写退回原因');if(!reason)return}if(['approve','unpublish','republish'].includes(type)&&!confirm({approve:'确认审核通过并发布当前版本？',unpublish:'下架后客户不能继续选入此课。历史询价与报价仍保留。',republish:'确认重新上架此课？'}[type]))return;await api('/manage/modules/'+id+'/review','POST',{action:type,reason,revision:S.edit.revision});S.courses=await api('/catalog?org='+S.org);await editView(id);toast('课程状态已更新');return}
if(a==='member-save'){const row=b.closest('tr');await api(`/orgs/${S.org}/members/${id}`,'PUT',{role:$('[name=member-role]',row).value,state:$('[name=member-state]',row).value});await refreshIdentity();await route();toast('成员权限已更新');return}
if(a==='grant'){const rows=await api('/inquiries?org='+S.org);modal('授权资源给项目',`<form id="grant-form" data-id="${id}">${select('选择询价项目','inquiry_id',rows.map(i=>[i.id,i.user_data.contact+' · '+i.snapshot.title]),rows[0]?.id,'required')}<div class="form-actions"><button class="btn primary" type="submit" ${rows.length?'':'disabled'}>确认授权</button></div></form>`);return}
if(a==='delete-asset'){if(!confirm('从当前草稿移除此资源？其他版本与项目授权不受影响。'))return;await api('/assets/'+id,'DELETE');await editView(S.edit.m.id);return}
if(a==='inquiry-state'){await api('/inquiries/'+id+'/state','PUT',{state:$('[name=inquiry-state]').value});await inquiryDetail(id);return}
if(a==='quote-new'){quoteModal(id);return}if(a==='quote-send'||a==='quote-accept'){if(!confirm(a==='quote-send'?'确认将此报价正式发送到客户账号？':'确认接受此报价的金额、包含范围和费用约定？'))return;await api('/quotes/'+id+'/action','POST',{action:a==='quote-send'?'send':'accept'});await inquiryDetail(S.inquiry.id);toast(a==='quote-send'?'报价已发送到客户账号':'报价已确认');return}
if(a==='quote-export'){const q=S.inquiry.quotes.find(x=>x.id===id),d=q.data;download('项目报价-v'+q.number+'.md',`# 项目报价 v${q.number}\n\n项目：${S.inquiry.snapshot.title}\n客户：${S.inquiry.user_data.contact}\n状态：${states[q.state]}\n总额：${money(d.total_fen)}\n有效期：${d.valid_until}\n\n`+[...d.module_lines,...d.extras].map(x=>`- ${x.label}：${money(x.amount_fen)}`).join('\n')+`\n优惠：${money(d.discount_fen)}\n包含：${d.included}\n不含：${d.excluded}\n税费：${d.tax_note}\n备注：${d.notes}`);return}
}catch(err){error(err)}}
document.addEventListener('click',clickAction);
document.addEventListener('submit',async e=>{const f=e.target;if(!f.id||f.id.startsWith('orgx-'))return;e.preventDefault();const b=$('button[type=submit]',f);if(b?.disabled)return;if(b)b.disabled=true;const d=Object.fromEntries(new FormData(f));try{
switch(f.id){
case 'auth-form':await api('/auth/'+f.dataset.mode,'POST',d);$('#dialog').close();await refreshIdentity();S.courses=await api('/catalog?org='+S.org);await route();toast('已登录');{const token=new URLSearchParams(location.search).get('invite');if(token)modal('接受机构邀请',`<p>当前登录邮箱：${esc(S.user.email)}</p>${action('接受邀请','accept-invite',token,'primary')}`)}break;
case 'plan-form':readPlan(f);await previewPlan();toast('教案已更新');break;
case 'inquiry-form':{const r=await api('/inquiries','POST',{...d,plan:planPayload(),request_key:f.dataset.key});$('#dialog').close();location.hash='inquiry?id='+r.id;break}
case 'agent-form':if(!requireLogin())break;$('#agent-result').innerHTML='<div class="loading">正在匹配模块、前置课程与排课容量…</div>';S.agent=await api('/agent/plan','POST',{...d,org_id:S.org,days:+d.days,daily_minutes:+d.daily_minutes,people:+d.people,budget_fen:d.budget===''?null:Math.round(+d.budget*100),required_ids:d.required?S.cart:[],equivalent:d.equivalent==='on'});$('#agent-result').innerHTML=agentResult(S.agent);break;
case 'module-form':{const data=readModule(f),mid=S.edit.m?.id;const r=await api(mid?'/manage/modules/'+mid:'/orgs/'+S.org+'/modules',mid?'PUT':'POST',{data,revision:S.edit.revision});location.hash='edit?id='+r.id;await editView(r.id);toast('草稿已保存');break}
case 'upload-form':if($('[name=file]',f).files[0].size>(S.uploadLimit||512)*1024*1024)throw new Error('文件超过上传上限');await api('/manage/modules/'+S.edit.m.id+'/assets','POST',new FormData(f));await editView(S.edit.m.id);toast('资源已上传');break;
case 'invite-form':{const r=await api('/orgs/'+S.org+'/invites','POST',d);$('#invite-result').innerHTML=`<p class="hint">${esc(r.note)}有效期 ${r.expires_days} 天。</p><div class="linkbox"><a href="${esc(r.url)}">${esc(r.url)}</a></div>`;break}
case 'grant-form':await api('/assets/'+f.dataset.id+'/grant','POST',d);$('#dialog').close();toast('项目资源已授权');break;
case 'quote-form':{const extras=lines(d.extras).map(l=>{const [label,n]=l.split('|').map(x=>x.trim());if(!label||!/^\d+(\.\d{1,2})?$/.test(n||''))throw new Error('费用格式应为：名称 | 金额，如 授课服务 | 2000');return {label,amount_fen:Math.round(+n*100)}});await api('/inquiries/'+f.dataset.id+'/quotes','POST',{extras,discount_fen:Math.round(+d.discount*100),valid_until:d.valid_until,included:d.included,excluded:d.excluded,tax_note:d.tax_note,notes:d.notes});$('#dialog').close();await inquiryDetail(f.dataset.id);toast('报价草稿已保存，由管理员正式发送');break}
case 'password-form':await api('/auth/password','POST',d);f.reset();toast('密码已更新，其他登录会话已失效');break;
case 'org-form':await api('/orgs/'+S.org,'PUT',{...d,agent_daily_limit:+d.agent_daily_limit});toast('机构设置已保存');await refreshOrgs();break;
case 'create-org-form':{const r=await api('/orgs','POST',d);await refreshIdentity();await refreshOrgs();await loadOrg(r.id);$('#org-select').value=r.id;location.hash='catalog';await route();toast('机构已创建');break}
case 'import-form':{const file=$('[name=file]',f).files[0];if(file.size>1024*1024)throw new Error('组合文件过大');const raw=JSON.parse(await file.text());let p;if(raw.schema==='course-studio/v1'){p=raw.plan;if(!p||!Array.isArray(p.ids))throw new Error('组合格式无效')}else if(raw.schema==='aigc-course-plan/v2'){const v=raw.state||raw;const ids=v.ids||v.selected;if(!Array.isArray(ids))throw new Error('旧版文件未包含课程编号');p={...planDefaults(),ids:ids.map(code=>{const c=S.courses.find(x=>x.code===code);if(!c)throw new Error('当前机构无课程 '+code);return c.id}),title:v.title||'',audience:{social:'社会学员',university:'开放大学学员',teacher:'教师',enterprise:'企业员工'}[v.audience]||'社会学员',daily_minutes:Math.round(Number(v.daily||6)*60),days:Number(v.target||0),notes:v.notes||'',equivalent:!!v.equivalent,org_id:S.org}}else throw new Error('不支持的组合文件格式');await api('/plans/validate','POST',{...planDefaults(),...p,org_id:p.org_id||S.org});$('#dialog').close();await setFromPlan(p);toast('组合已载入，请核对模块与价格');break}
}
}catch(err){if(f.id==='agent-form'&&$('#agent-result'))$('#agent-result').innerHTML='';error(err)}finally{if(b)b.disabled=false}});
async function refreshOrgs(){S.orgs=await api('/orgs');if(!S.orgs.some(o=>o.id===S.org)){if(S.orgs.length)await loadOrg(S.orgs[0].id);else{S.org='';S.courses=[];S.cart=[]}}$('#org-select').innerHTML=S.orgs.map(o=>`<option value="${esc(o.id)}" ${o.id===S.org?'selected':''}>${esc(o.name)}</option>`).join('')}
async function pathsView(){if(!S.presets)S.presets=await(await fetch('/static/presets.json')).json();$('#content').innerHTML=head('课程路径与组合模板','涵盖创作基础、工具应用、案例实训与商业交付，按学习目标规划培训路径。')+`<div class="path-flow">${Object.entries(cats).map(([k,v])=>`<div class="type-${k}"><b>${k} · ${v}</b><p>${{F:'需求 → 选题 → 脚本 → 分镜 → 镜头 → 审核',T:'画布 / 转绘 / 导演台，选择适合项目的工具路径',P:'广告、口播、短剧、转绘与教学视频案例',B:'报价、作品集、客户沟通与交付管理'}[k]}</p><div class="path-nodes">${S.courses.filter(c=>c.category===k).map(c=>`<button class="chip" data-action="path-node" data-id="${c.id}" title="${esc(c.title)}">${c.code}</button>`).join('')}</div></div>`).join('')}</div><p class="hint">四类模块可交叉编排。点击编号查看其前置与后续关系；有同等基础的学员可按需求跳过先修。</p><h2>常用培训组合</h2><div class="course-grid">${S.presets.presets.map((p,i)=>{const codes=p.days.flat(),valid=codes.every(code=>S.courses.some(c=>c.code===code&&c.title===S.presets.titles[code]));return `<section class="panel"><h3>${esc(p.name)}</h3><p>${esc(p.result)}</p><p class="hint">${p.days.map((ds,n)=>`第${n+1}天：${ds.join(' → ')}`).join('<br>')}</p><button class="btn primary" data-action="preset" data-id="${i}" ${valid?'':'disabled'}>${valid?'载入并核对方案':'当前机构课程库不适用'}</button></section>`}).join('')}</div>`}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;try{if(b.dataset.action==='path-node'){const c=S.courses.find(x=>x.id===b.dataset.id),before=c.prereq_ids.map(id=>S.courses.find(x=>x.id===id)),after=S.courses.filter(x=>x.prereq_ids.includes(c.id));modal(c.code+' · '+c.title,`<div class="panel"><h3>先修条件 · ${c.prereq_mode==='any'?'任一满足':'全部满足'}</h3>${before.length?list(before.map(x=>x?x.code+' '+x.title:'课程暂不可用')):'<p>无需必修先修课程。</p>'}<h3>当前模块</h3><p>${esc(c.intro)}</p><h3>可继续学习</h3>${after.length?list(after.map(x=>x.code+' '+x.title)):'<p>可按作品方向自由组合后续模块。</p>'}</div>`)}if(b.dataset.action==='preset'&&!b.disabled){const p=S.presets.presets[+b.dataset.id];if(S.cart.length&&!confirm('用此模板替换当前组合？已保存方案不受影响。'))return;const ids=p.days.flat().map(code=>S.courses.find(c=>c.code===code).id);await setFromPlan({...planDefaults(),org_id:S.org,ids,title:p.name,days:p.days.length,notes:'预期成果：'+p.result});toast('已载入模板，请查看前置与课时核对结果')}}catch(err){error(err)}});
document.addEventListener('change',async e=>{try{if(e.target.id==='org-select'){await loadOrg(e.target.value);location.hash='catalog';await route()}if(e.target.id==='category-filter'){S.category=e.target.value;catalog()}}catch(err){error(err)}});
document.addEventListener('input',e=>{if(e.target.id==='course-search'){S.search=e.target.value;const pos=e.target.selectionStart;catalog();$('#course-search').focus();$('#course-search').setSelectionRange(pos,pos)}});
window.addEventListener('hashchange',route);
init().catch(error);

// Native details keep grouped navigation accessible with keyboard and touch.
document.addEventListener('toggle',e=>{if(e.target.matches('.nav-group')&&e.target.open)$$('.nav-group').forEach(x=>{if(x!==e.target)x.open=false})},true);
document.addEventListener('click',e=>{$$('.account-menu[open]').forEach(x=>{if(!x.contains(e.target))x.open=false});if(!e.target.closest('#navigation'))$$('.nav-group[open]').forEach(x=>{if(matchMedia('(max-width:850px)').matches)x.open=false})});
document.addEventListener('keydown',e=>{if(e.key==='Escape')$$('.account-menu[open],.nav-group[open]').forEach(x=>{if(x.matches('.account-menu')||matchMedia('(max-width:850px)').matches)x.open=false});if(e.target.matches('.detail-tabs [role=tab]')&&['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const tabs=$$('.detail-tabs [role=tab]');let n=tabs.indexOf(e.target);n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(n+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[n].click()}});
$('#dialog').addEventListener('close',()=>{$$('video,audio',$('#dialog')).forEach(x=>x.pause());$('#dialog-content').replaceChildren();$('#dialog').classList.remove('course-dialog')});

matchMedia('(max-width:850px)').addEventListener('change',nav);
